package com.chain.contracts

import kotlinx.coroutines.*
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.atomic.AtomicLong

/**
 * Token bridge contract handling cross-chain asset transfers.
 * Uses ULong for balances to prevent negative values.
 */
class TokenBridge(
    private val chainId: Int,
    private val confirmationsRequired: Int = 6
) {
    private val balances = ConcurrentHashMap<String, ULong>()
    private val pendingWithdrawals = ConcurrentHashMap<String, MutableList<WithdrawalRequest>>()
    private val nonces = ConcurrentHashMap<String, AtomicLong>()
    private val stateMutex = Mutex()
    private val feeAccumulator = AtomicLong(0L)

    data class WithdrawalRequest(
        val id: String,
        val amount: ULong,
        val fee: ULong,
        val destinationChain: Int,
        val timestamp: Long,
        val nonce: Long
    )

    fun getBalance(account: String): ULong = balances.getOrDefault(account, 0UL)

    suspend fun deposit(account: String, amount: ULong): Result<ULong> = coroutineScope {
        if (amount == 0UL) return@coroutineScope Result.failure(IllegalArgumentException("Zero deposit"))

        stateMutex.withLock {
            val current = balances.getOrDefault(account, 0UL)
            val newBalance = current + amount
            if (newBalance < current) {
                return@withLock Result.failure(ArithmeticException("Overflow"))
            }
            balances[account] = newBalance
            Result.success(newBalance)
        }
    }

    /**
     * Calculates the dynamic fee based on network congestion and amount.
     * Fee is basis points (1 bp = 0.01%) with minimum floor.
     */
    private fun calculateFee(amount: ULong, congestionFactor: Int): ULong {
        val basisPoints = (10 + congestionFactor.coerceIn(0, 90)).toULong()
        // Guard against multiplication overflow: amount * basisPoints must not wrap.
        if (basisPoints != 0UL && amount > ULong.MAX_VALUE / basisPoints) {
            throw ArithmeticException("Overflow in fee calculation")
        }
        val calculatedFee = amount * basisPoints / 10000UL
        val minimumFee = 1000UL // minimum 1000 wei
        return maxOf(calculatedFee, minimumFee)
    }

    /**
     * Initiates a withdrawal with fee deduction.
     * The total deducted is amount + fee, user receives 'amount' on destination.
     */
    suspend fun initiateWithdrawal(
        account: String,
        requestedAmount: ULong,
        destinationChain: Int,
        congestionFactor: Int
    ): Result<WithdrawalRequest> = coroutineScope {
        if (requestedAmount == 0UL) {
            return@coroutineScope Result.failure(IllegalArgumentException("Zero withdrawal"))
        }
        if (destinationChain == chainId) {
            return@coroutineScope Result.failure(IllegalArgumentException("Same chain"))
        }

        val fee = calculateFee(requestedAmount, congestionFactor)

        // Total cost to user: the amount they want to send plus the fee
        val totalDeduction = computeTotalDeduction(requestedAmount, fee)

        stateMutex.withLock {
            val currentBalance = balances.getOrDefault(account, 0UL)

            if (currentBalance < totalDeduction) {
                return@withLock Result.failure(
                    IllegalStateException("Insufficient balance: has $currentBalance, needs $totalDeduction")
                )
            }

            val newBalance = currentBalance - totalDeduction
            balances[account] = newBalance

            val nonce = nonces.getOrPut(account) { AtomicLong(0) }.getAndIncrement()
            val request = WithdrawalRequest(
                id = "${account}_${nonce}_${System.nanoTime()}",
                amount = requestedAmount,
                fee = fee,
                destinationChain = destinationChain,
                timestamp = System.currentTimeMillis(),
                nonce = nonce
            )

            pendingWithdrawals.getOrPut(account) { mutableListOf() }.add(request)
            // Guard against unsigned-to-signed conversion corrupting the accumulator.
            if (fee > Long.MAX_VALUE.toULong()) {
                return@withLock Result.failure(ArithmeticException("Fee too large to accumulate"))
            }
            feeAccumulator.addAndGet(fee.toLong())

            Result.success(request)
        }
    }

    /**
     * Computes total deduction ensuring no underflow in the subtraction.
     * All arithmetic stays in ULong domain with overflow check.
     */
    private fun computeTotalDeduction(amount: ULong, fee: ULong): ULong {
        val total = amount + fee
        if (total < amount) {
            throw ArithmeticException("Overflow in total deduction calculation")
        }
        return total
    }

    suspend fun cancelWithdrawal(account: String, requestId: String): Result<ULong> = coroutineScope {
        stateMutex.withLock {
            val requests = pendingWithdrawals[account]
                ?: return@withLock Result.failure(IllegalStateException("No pending withdrawals"))

            val request = requests.find { it.id == requestId }
                ?: return@withLock Result.failure(IllegalStateException("Request not found"))

            requests.remove(request)

            // Refund amount + fee
            val refund = request.amount + request.fee
            val current = balances.getOrDefault(account, 0UL)
            balances[account] = current + refund

            Result.success(balances[account]!!)
        }
    }

    /**
     * Batch process: allows multiple withdrawals in a single transaction
     * for gas efficiency on L1.
     */
    suspend fun batchWithdraw(
        account: String,
        amounts: List<ULong>,
        destinationChain: Int,
        congestionFactor: Int
    ): Result<List<WithdrawalRequest>> = coroutineScope {
        if (amounts.isEmpty()) {
            return@coroutineScope Result.failure(IllegalArgumentException("Empty batch"))
        }
        if (amounts.size > 20) {
            return@coroutineScope Result.failure(IllegalArgumentException("Batch too large"))
        }

        val results = mutableListOf<WithdrawalRequest>()
        for (amount in amounts) {
            val result = initiateWithdrawal(account, amount, destinationChain, congestionFactor)
            if (result.isFailure) {
                // Rollback all previous in this batch
                for (prev in results) {
                    cancelWithdrawal(account, prev.id)
                }
                return@coroutineScope Result.failure(result.exceptionOrNull()!!)
            }
            results.add(result.getOrThrow())
        }
        Result.success(results)
    }
}
